.resource_support{
  // height: 100%;
  height: 90vh;
  // overflow-y: auto;
  display: flex;
  justify-content: space-between;
  .resource_card{
    background: #fff;
    box-shadow: 0 4px 25px 0 #e9f0ff;
    padding: 10px;
    .card_title{
      display: flex;
      align-items: center;
      font-size: 15px;
      line-height: 20px;
      font-family: '黑体';
      margin-bottom: 10px;
      img{margin-right: 10px;}
    }
    .card_content{
      .card_list_item{
        display: flex;
        justify-content: space-between;
        font-size: 14px;
        margin-bottom: 12px;
        cursor: pointer;
        &:hover{
          color: #1061ff;
        }
        &:last-child{
          margin-bottom: 0px
        }
        .item_left{
          width: calc(100% - 50px);
          white-space: nowrap;
          overflow: hidden;
          text-overflow: ellipsis;
          padding-right: 20px;
          .item_index{
            margin-right: 20px;
            color: #999;
          }
        }
        .item_right{
          width: 45px;
        }
        &:first-child{
          .item_index{
            color: #ffd02b;
          }
        }
        &:nth-child(2) {
          .item_index{
            color: #6ca3e2;
          }
        }
        &:nth-child(3) {
          .item_index{
            color: #d5a38e;
          }
        }
      }
    }


    .card_pai{
      ::v-deep .ictHome-rc .el-table .el-table__cell{
        height: 35px;
      }
      .tag{
        width: 20px;
        height: 20px;
        text-align: center;
        margin: 0 auto;
        line-height: 20px;
        border-radius: 50%;
        background: #d9e2e9;
        color: #333;
      }
      .tag0{
        background: #e3593c;
        color: #fff;
      }
      .tag1{
        background: #ea993f;
        color: #fff;
      }
      .tag2{
        background: #f3c843;
        color: #fff;
      }
    }
  }
  .left{
    width: 919px;
    height: 145%;
    .left_top{
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 20px;
      .resource_tabs{
        display: flex;
        color: #333;
        position: relative;
        .is_active_line{
          position: absolute;
          height: 2px;
          width: 120px;
          background: #1061ff;
          bottom: 0px;
          left: 0px;
          transition: all 0.3s;
        }
        .resource_tabs_item{
          margin-right: 25px;
          cursor: pointer;
          font-size: 16px;
          display: flex;
          justify-content: center;
          align-items: center;
          padding: 8px;
          padding-bottom: 12px;
          width: 120px;
          img{
            margin-right: 10px
          }
        }
      }
      .question_search{
        overflow: hidden;
        display: flex;
        align-items: center;
        ::v-deep .el-input__inner{
          background-color: #fff;
          border-radius: 30px;
          // border: 1px solid #1061ff;
          border: 1px solid rgba(200,255,255,0.9);
          color: #000;
        }
        ::v-deep .el-input_placeholder{
          color: #000;
        }
        ::v-deep .el-input__icon{
          // color: #1061ff;
          color: #007bff;
        }
        .search_btn{
          white-space: nowrap;
          background-image: url('../img/questionsearch.png');
          background-size: 100% 100%;
          height: 40px;
          line-height: 40px;
          text-align: center;
          color: #fff;
          padding: 0 20px;
          margin-left: 20px;
          cursor: pointer;
        }
      }
    }
    .left_content{
      height: calc(100% - 62px);
      overflow: auto;
    }
  }
  .right{
    width: 334px;
    height: 100%;
    .submit-btn{
      padding: 10px;
      margin-bottom: 15px;
      cursor: pointer;
      .btn_box{
        background: #eef8ff;
        display: flex;
        justify-content: center;
        align-items: center;
        height: 60px;
        font-family: '黑体';
        font-size: 18px;
        font-weight: bold;
        img{margin-right: 20px}
      }
    }

    .btn_box2{
      display: flex;
      align-items: center;
      justify-content: center;
      height: 61px;
      width: 100%;
      border-radius: 10px;
      font-size: 22px;
      line-height: 61px;
      text-align: center;
      cursor: pointer;
      img{margin-right: 30px}

    }
    .submit_question_btn{
      background-image: url('../img/submitbtnback.png');
      background-size: 100% 100%;
      color: #fff;
      margin-bottom: 15px;
    }
    .my_btn{
      border: 1px solid rgba(76,137,255,1);
      margin-bottom: 15px;
    }
  }
}
::-webkit-scrollbar{
  width: 5px;
  height: 5px;
}
::v-deep ::-webkit-scrollbar-button{
  display: none
}
::-webkit-scrollbar-thumb{
  background: #bed4ff;
  border-radius: 3px
}
::-webkit-scrollbar-track{
  margin: 5px
}
